#include <iostream>
using namespace std;

struct Drone {
    int id;
    int battery;
};

void recharge(Drone &d, int amount) {
    d.battery += amount;
    if (d.battery > 100) {
        d.battery = 100;
    }
}

int main() {
    int id, battery, amount;
    cin >> id >> battery >> amount;

    Drone d = {id, battery};
    recharge(d, amount);
    cout << "DRONE " << d.id << " BATTERY: " << d.battery << endl;
    return 0;
}

