#include <iostream>
#include <cmath>
using namespace std;

struct Point {
    int x;
    int y;
};

int manhattan_dist(const Point &a, const Point &b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}

int main() {
    int x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;

    Point a = {x1, y1};
    Point b = {x2, y2};
    int dist = manhattan_dist(a, b);
    cout << "DISTANCE: " << dist << endl;
    return 0;
}

